global_css:
body{background:linear-gradient(180deg,#f4f1e8 0%, #efeadf 100%) !important;background-attachment:fixed}
.glass-card,.modpack-card,.profile-card{background:#fdfcf8 !important;transition:transform .16s ease, box-shadow .16s ease, border-color .16s ease}
.glass-card:hover{transform:translateY(-1px);box-shadow:0 6px 20px rgba(120,80,40,0.1) !important;border-color:rgba(200,97,63,0.3) !important}
.btn-primary{background:linear-gradient(180deg,#d27a4f 0%, #c8613f 100%) !important;border:none !important;color:#fff !important;font-weight:600;border-radius:999px !important;box-shadow:0 2px 8px rgba(200,97,63,0.3) !important}
.btn:not(.btn-primary){border-radius:999px !important}
.pill,.tag{border-radius:999px !important}
h1,h2,h3,.card-title{letter-spacing:-.015em}
